                    "authorAttribution": {
                        "displayName": "Steph Curtis (stephstwogirls)",
                        "uri": "https://www.google.com/maps/contrib/116675999149072294611/reviews",
                        "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXxTYk_LeR5bxC-KxV2xjdl_JauA3UusuvS3j-UCecwV2tV68A5=s128-c0x00000000-cc-rp-mo"
