            "reviews": [
                {
                    "name": "places/ChIJPfEQoU5awokRNdBwGAHP83E/reviews/ChZDSUhNMG9nS0VJQ0FnSUNyaHRYYVRnEAE",
                    "relativePublishTimeDescription": "a month ago",
                    "rating": 5,
                    "text": {
                        "text": "I love visiting the New York Transit Museum. This location is at Grand Central Terminal at 89 East 42nd Street, New York, NY. This is the se one location that I visit. This time we only went in to buy a plate holder. However, the exhibition was awesome. We walked throughout the whole space which offers great subway memorabilia. The staff is friendly and helpful!",
                        "languageCode": "en"
                    },
                    "originalText": {
                        "text": "I love visiting the New York Transit Museum. This location is at Grand Central Terminal at 89 East 42nd Street, New York, NY. This is the se one location that I visit. This time we only went in to buy a plate holder. However, the exhibition was awesome. We walked throughout the whole space which offers great subway memorabilia. The staff is friendly and helpful!",
                        "languageCode": "en"
                    },
                    "authorAttribution": {
                        "displayName": "Miriam Noyola",
                        "uri": "https://www.google.com/maps/contrib/113020832504068736638/reviews",
                        "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVgVIsUixO8fM_KsCIn71tKnKA89l1kvfxvNVIy384yY1fglsC2=s128-c0x00000000-cc-rp-mo-ba7"
                    },
                    "publishTime": "2024-07-06T12:43:01Z"
                },
                {
                    "name": "places/ChIJPfEQoU5awokRNdBwGAHP83E/reviews/ChZDSUhNMG9nS0VJQ0FnSURycFpPNklBEAE",
                    "relativePublishTimeDescription": "a month ago",
                    "rating": 5,
                    "text": {
                        "text": "Always fun, always interesting, and always friendly! There is plenty of merchandise for adults, children, adults who feel like old children, and everything from historic artifacts and materials for sale, art, books, clothing, and a lot of fun new MTA merchandise…all of the above with offerings for both adults and children! Whether you are a serious MTA or transit fan, looking for a more unique NYC souvenir which is far better than the stuff random souvenir shops sell, or whether you’re looking for a gift for a friend or a child, the Transit Museum gift shops have it all! Don’t forget to join the Transit Museum as a member for perks and special member opportunities! (Photos with this review from the annual Holiday Train Show at the GCT location)",
                        "languageCode": "en"
                    },
                    "originalText": {
                        "text": "Always fun, always interesting, and always friendly! There is plenty of merchandise for adults, children, adults who feel like old children, and everything from historic artifacts and materials for sale, art, books, clothing, and a lot of fun new MTA merchandise…all of the above with offerings for both adults and children! Whether you are a serious MTA or transit fan, looking for a more unique NYC souvenir which is far better than the stuff random souvenir shops sell, or whether you’re looking for a gift for a friend or a child, the Transit Museum gift shops have it all! Don’t forget to join the Transit Museum as a member for perks and special member opportunities! (Photos with this review from the annual Holiday Train Show at the GCT location)",
                        "languageCode": "en"
                    },
                    "authorAttribution": {
                        "displayName": "Kevin Cartwright",
                        "uri": "https://www.google.com/maps/contrib/111136747497770102216/reviews",
                        "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVnFnX499z18w5QTEjXuqVB0joXi1208eRtu1zFjZ3cAoyI1B8-=s128-c0x00000000-cc-rp-mo-ba4"
