            "reviews": [
                {
                    "name": "places/ChIJ55dWS_lYwokR6c2IHYG97O8/reviews/ChZDSUhNMG9nS0VJQ0FnSUNqaHVuSlZREAE",
                    "relativePublishTimeDescription": "4 months ago",
                    "rating": 1,
                    "text": {
                        "text": "Embrassing and unprofessional to see firefighters from FDNY special operations in Roosevelt island decided to covered up their license plate with a plastic cover on April 20th 2024 2pm. Clearly shows these firefighters don't follow the laws and a bad reflection of your department!",
                        "languageCode": "en"
                    },
                    "originalText": {
                        "text": "Embrassing and unprofessional to see firefighters from FDNY special operations in Roosevelt island decided to covered up their license plate with a plastic cover on April 20th 2024 2pm. Clearly shows these firefighters don't follow the laws and a bad reflection of your department!",
