                {
                    "name": "places/ChIJ7aCfw2C3t4kRvb6eK8AmDGQ/reviews/ChZDSUhNMG9nS0VJQ0FnSUM3eElmTEt3EAE",
                    "relativePublishTimeDescription": "a week ago",
                    "rating": 5,
                    "text": {
                        "text": "We booked the other location for a birthday but declined entry due to malfunctioning bathrooms. They were generous enough to give us a gift card, so we just came here instead. Good atmosphere and vibe. The food was tasty and original. We enjoyed every minute. If you don't like sushi rolls, kimchi fried rice and eggplant nigiri are top notch. Bar is also an option if you don't want to sit at a table or booth. Private parking garage nearby if street parking is not available.",
                        "languageCode": "en"
                    },
                    "originalText": {
