                    },
                    "publishTime": "2024-03-02T20:49:34Z"
                },
                {
                    "name": "places/ChIJp3I0c7jJt4kRE42L4kQW5zY/reviews/ChdDSUhNMG9nS0VJQ0FnSURMNUpQLTRnRRAB",
                    "relativePublishTimeDescription": "a month ago",
                    "rating": 5,
                    "text": {
                        "text": "I purchased the pizza and it was absolutely delicious. I also purchased the 12 oz ginger shot. I added the shot to juice I had at home and it reminded me of the Jamu I love so much in Bali. Highly recommend the business.",
                        "languageCode": "en"
                    },
