                        "displayName": "Shannon Russell",
                        "uri": "https://www.google.com/maps/contrib/100529764346161747003/reviews",
                        "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUjfczLp0Wm7oOI7qHIOtpFOH2xqAvqeUmu1cbho-JyqyTHvrvx=s128-c0x00000000-cc-rp-mo-ba3"
