                        "uri": "https://www.google.com/maps/contrib/103461087359179833089/reviews",
                        "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVB0A7TtKfgRzA64t7Q2XCyqHQVvasNCP0JvfxsT5iqHOnba_sj=s128-c0x00000000-cc-rp-mo-ba5"
