            "reviews": [
                {
                    "name": "places/ChIJTS2ac_q3t4kRYIlCRzGad1Y/reviews/ChZDSUhNMG9nS0VJQ0FnSUM3cmJUc1JBEAE",
                    "relativePublishTimeDescription": "in the last week",
                    "rating": 4,
                    "text": {
                        "text": "Was excited to try this restaurant, being a vegetarian and to have so many choices! Enjoyed the food, Asian inspired and a mish mash of flavors, was decent. Seemed mushroom heavy with its use across the menu. Personally, would not order the shiitake crispy rice again as was really crunchy. For the small portion sizes doled out, seemed a bit over priced! But, definitely appreciated the choices available and would visit again to try other options.",
                        "languageCode": "en"
                    },
                    "originalText": {
                        "text": "Was excited to try this restaurant, being a vegetarian and to have so many choices! Enjoyed the food, Asian inspired and a mish mash of flavors, was decent. Seemed mushroom heavy with its use across the menu. Personally, would not order the shiitake crispy rice again as was really crunchy. For the small portion sizes doled out, seemed a bit over priced! But, definitely appreciated the choices available and would visit again to try other options.",
                        "languageCode": "en"
                    },
