                {
                    "name": "places/ChIJs7PZzcO3t4kRxQIgwG5AjtQ/reviews/ChdDSUhNMG9nS0VJQ0FnSUREaXRmcDNRRRAB",
                    "relativePublishTimeDescription": "4 months ago",
                    "rating": 5,
                    "text": {
                        "text": "We were visiting from NewJersey and looking to stop by to eat. It was early evening, around 4pm. I got a tandoori paneer bowl. That is THE best restaurant food I ate in the recent times. I loved their service, the quality of their ingredients, and their innovative soft serve (masala chai flavored !). This is the THE restaurant to go to in this area. Do visit and you won't be disappointed.",
                        "languageCode": "en"
                    },
                    "originalText": {
                        "text": "We were visiting from NewJersey and looking to stop by to eat. It was early evening, around 4pm. I got a tandoori paneer bowl. That is THE best restaurant food I ate in the recent times. I loved their service, the quality of their ingredients, and their innovative soft serve (masala chai flavored !). This is the THE restaurant to go to in this area. Do visit and you won't be disappointed.",
                        "languageCode": "en"
