            "reviews": [
                {
                    "name": "places/ChIJ19EBtIW5t4kRlMYSEamFscw/reviews/ChdDSUhNMG9nS0VJQ0FnSUR6bDh6VG9RRRAB",
                    "relativePublishTimeDescription": "2 months ago",
                    "rating": 5,
                    "text": {
                        "text": "Fast and caring service. Really good food. Highly recommend the thali.\n\nOnly thing I would improve on their spread is change up one of the chicken dishes because they already serve chicken bbq. It’s just too much chicken for our preference. Maybe a different veg option would be great.\n\nThe spinach was our favorite followed by the lamb, goat, and lentils. The chickpeas were last.\n\nChai was a lovely compliment with the dishes.",
                        "languageCode": "en"
                    },
                    "originalText": {
