                        "uri": "https://www.google.com/maps/contrib/107329130242225383029/reviews",
                        "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjU84g7MEHAMzOAlmjISzpLWR5iPW_1jOy44VLmGoQL9v2w4pAxVvQ=s128-c0x00000000-cc-rp-mo-ba5"
